export function usageRequestFixture(mode: string | null) {
  const records =
    mode === 'empty'
      ? []
      : mode === 'overflow'
        ? Array.from({ length: 200 }, (_, i) => ({ ...USAGE_REQUEST_FACTS[i % 8]!, id: `request-${i}` }))
        : mode === 'localized'
          ? USAGE_REQUEST_FACTS.map((row) => ({
              ...row,
              model: `${row.model} mit besonders großem Kontextfenster`,
              endpoint: `${row.endpoint}/workspace/project/long-resource-name`,
            }))
          : USAGE_REQUEST_FACTS
  return {
    records,
    expandedId: mode === 'overflow' ? 'request-3' : 'req_8f2183',
    copy: mode === 'localized' ? GERMAN_REQUEST_COPY : USAGE_REQUEST_COPY,
  }
}
